INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT142-S1-Q5$batch02$, 142, 1, 5, $batch02$Flaw$batch02$, $batch02$Critic: Fillmore, an influential television executive, argues that watching television regularly is not detrimental to very young children. Fillmore bases this on the claim, which I grant, that children can learn much that is beneficial from television. But we should reject Fillmore’s argument, because clearly it is to Fillmore’s benefit to convince parents that television is not harmful to their children.$batch02$, $batch02$Which one of the following most accurately describes a flaw in the critic’s reasoning?$batch02$, $batch02$C$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=142 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT142-S1-Q5$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$It takes a necessary condition for something’s being harmful to be a sufficient condition for being harmful.$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT142-S1-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$It concludes that something is true merely on the grounds that there is no evidence to the contrary.$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT142-S1-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$It rejects an argument solely on the grounds that the argument could serve the interests of the person making that argument.$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT142-S1-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$It is based on an appeal to the views of someone with questionable authority on the subject matter.$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT142-S1-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$It bases its conclusion on claims that are inconsistent with one another.$batch02$, $batch02$Compatible$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT142-S1-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT142-S1-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$We should reject Fillmore's argument.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Fillmore benefits if parents believe television is harmless.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Fillmore has a motive. Does a motive make his argument wrong? A car salesman who tells you the brakes work has a reason to say so, and the brakes may still work. The critic never says what is wrong with Fillmore's reasoning. In fact, the critic grants his premise.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Expect the ad hominem answer: rejecting an argument because of the arguer's interests.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT142-S1-Q5$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$No conditional about harm is reversed. The critic is not reasoning about what makes something harmful at all.$batch02$), ($batch02$B$batch02$, $batch02$The critic does not claim anything is true for lack of contrary evidence. The reason offered is Fillmore's self-interest.$batch02$), ($batch02$C$batch02$, $batch02$The only reason to reject Fillmore's argument is that it serves Fillmore. A self-serving argument can still be sound. The critic attacks the arguer's motive instead of the argument.$batch02$), ($batch02$D$batch02$, $batch02$The critic is not relying on Fillmore's authority; the critic is rejecting Fillmore's view. Nobody's questionable authority supports the conclusion.$batch02$), ($batch02$E$batch02$, $batch02$Granting a premise while rejecting the argument is not inconsistent. You can accept that children learn from television and still deny that television is harmless. The critic's claims fit together; they just do not support rejecting Fillmore.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT142-S1-Q5$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
